"""UE editor repair from graphs generated by the production C# builder.

prepare validates copies first. apply also backs up and updates original materials.
"""
import json
from pathlib import Path
import unreal

lib=unreal.MaterialEditingLibrary

def custom_inputs(names):
    result=[]
    for name in names:
        item=unreal.CustomInput()
        item.set_editor_property('input_name',name)
        result.append(item)
    return result

def build(material, graph):
    lib.delete_all_material_expressions(material)
    material.set_editor_property('blend_mode',unreal.BlendMode.BLEND_MASKED)
    material.set_editor_property('dither_opacity_mask',graph['DitherOpacityMask'])
    material.set_editor_property('opacity_mask_clip_value',.5)
    nodes={}
    for entry in graph['Nodes']:
        kind=entry['Kind'];data=entry['Data']
        cls={'MaterialUv':unreal.MaterialExpressionTextureCoordinate,
             'MaterialVertexColor':unreal.MaterialExpressionVertexColor,
             'MaterialSample':unreal.MaterialExpressionTextureSample,
             'MaterialCustom':unreal.MaterialExpressionCustom}[kind]
        node=lib.create_material_expression(material,cls,-800+(entry['Id']%4)*200,(entry['Id']//4)*200)
        nodes[entry['Id']]=node
        if kind=='MaterialUv':node.set_editor_property('coordinate_index',data['Channel'])
        elif kind=='MaterialVertexColor':
            # The editor's first VertexColor pin masks out alpha, unlike our native link.
            rgba=lib.create_material_expression(material,unreal.MaterialExpressionCustom,-1000,400)
            rgba.set_editor_property('code','return float4(rgb,a);')
            rgba.set_editor_property('output_type',unreal.CustomMaterialOutputType.CMOT_FLOAT4)
            rgba.set_editor_property('inputs',custom_inputs(['rgb','a']))
            assert lib.connect_material_expressions(node,'',rgba,'rgb')
            assert lib.connect_material_expressions(node,'A',rgba,'a')
            nodes[entry['Id']]=rgba
        elif kind=='MaterialSample':
            node.set_editor_property('texture',unreal.load_asset(data['Path']))
            node.set_editor_property('sampler_type',unreal.MaterialSamplerType.SAMPLERTYPE_COLOR if data['Srgb'] else unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_COLOR)
            if data['MipBias'] is not None:
                node.set_editor_property('mip_value_mode',unreal.TextureMipValueMode.TMVM_MIP_BIAS)
        elif kind=='MaterialCustom':
            node.set_editor_property('code',data['Code'])
            node.set_editor_property('description',data['Label'])
            node.set_editor_property('output_type',getattr(unreal.CustomMaterialOutputType,'CMOT_FLOAT'+str(data['Dimensions'])))
            node.set_editor_property('inputs',custom_inputs(x['Item1'] for x in data['Inputs']))
    def connect(link,target,pin):
        output={0:'',1:'R',2:'G',4:'B',8:'A',7:'RGB',15:'RGBA'}[link['Mask']]
        if isinstance(nodes[link['Expression']],unreal.MaterialExpressionCustom) and link['Mask']==15:
            output=''
        assert lib.connect_material_expressions(nodes[link['Expression']],output,target,pin),(target.get_name(),pin)
    for entry in graph['Nodes']:
        node=nodes[entry['Id']];data=entry['Data']
        if entry['Kind']=='MaterialSample':
            pins=list(lib.get_material_expression_input_names(node))
            connect(data['Uv'],node,pins[0])
            if data['MipBias'] is not None:
                connect(data['MipBias'],node,'Bias')
        elif entry['Kind']=='MaterialCustom':
            for item in data['Inputs']:connect(item['Item2'],node,item['Item1'])
    properties={'BaseColor':unreal.MaterialProperty.MP_BASE_COLOR,'Normal':unreal.MaterialProperty.MP_NORMAL,
                'Roughness':unreal.MaterialProperty.MP_ROUGHNESS,'Metallic':unreal.MaterialProperty.MP_METALLIC,
                'EmissiveColor':unreal.MaterialProperty.MP_EMISSIVE_COLOR,'Opacity':unreal.MaterialProperty.MP_OPACITY_MASK}
    for output,link in graph['Outputs'].items():
        assert lib.connect_material_property(nodes[link['Expression']],'',properties[output]),output
    assert not lib.recompile_material(material),material.get_name()
    assert lib.get_statistics(material).num_pixel_shader_instructions>0,material.get_name()
    assert unreal.EditorAssetLibrary.save_loaded_asset(material,False)

def repair(graph_file, apply=False):
    graphs=json.loads(Path(graph_file).read_text(encoding='utf-8'))
    for graph in graphs:
        path=graph['Package'];original=unreal.load_asset(path)
        assert isinstance(original,unreal.Material),path
        candidate_path='/Game/MeddleHairAudit/Candidates/'+original.get_name()
        candidate=unreal.load_asset(candidate_path) if unreal.EditorAssetLibrary.does_asset_exist(candidate_path) else unreal.EditorAssetLibrary.duplicate_asset(path,candidate_path)
        build(candidate,graph)
    if apply:
        for graph in graphs:
            path=graph['Package'];original=unreal.load_asset(path)
            backup='/Game/MeddleHairAudit/Before/'+original.get_name()
            if unreal.EditorAssetLibrary.does_asset_exist(backup):
                raise RuntimeError('Backup already exists; inspect before repeating repair: '+backup)
            before=unreal.EditorAssetLibrary.duplicate_asset(path,backup)
            assert before and unreal.EditorAssetLibrary.save_loaded_asset(before,False)
            build(original,graph)
            report=Path(unreal.Paths.project_content_dir())/(path.removeprefix('/Game/')+'.formula.json')
            data=json.loads(report.read_text(encoding='utf-8-sig'))
            report.with_suffix('.json.before-hair-repair').write_bytes(report.read_bytes())
            for key in ['Reference','AlphaMode','DitherOpacityMask','Adaptation']:data[key]=graph[key]
            report.write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding='utf-8')
    unreal.log(f'MEDDLE_HAIR_{"APPLIED" if apply else "PREPARED"} {len(graphs)}')
